package com.powercms.cms.sitepackage.web;
import com.powercms.cms.sitepackage.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/sites/{siteId}/css-classes") public class CssClassController { private final TemplateService templates; private final CssClassService classes; CssClassController(TemplateService t,CssClassService c){templates=t;classes=c;} @GetMapping @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'read')") public CssClassService.Result list(@PathVariable UUID siteId,@RequestParam(defaultValue="false") boolean preview){var project=templates.listProjects(siteId).stream().filter(x->"FTL".equalsIgnoreCase(x.projectType())).findFirst();return project.map(x->classes.load(x.id(),preview)).orElse(new CssClassService.Result(List.of(),List.of("template project unavailable")));}}
